"""
Generador de casos de test ciego TEST10 para Clases 01 a 13 (MOTOR).
Exactamente 13 clases x 6 casos = 78 registros (2 L1, 2 L2, 2 L3 por clase).
Totalmente independientes, sin solapamiento léxico ni contaminación con Fase 10 o benchmarks.
"""

from typing import List, Dict
import sys
from pathlib import Path

sys.path.insert(0, str(Path("backend").resolve()))
from src.core.diagnostico.taxonomia_sistemas import FALLA_A_SISTEMA

keys = list(FALLA_A_SISTEMA.keys())

CLASE_01 = keys[0]   # Falla en bujias o bobinas de encendido (misfire)
CLASE_02 = keys[1]   # Bomba de gasolina quemada o con baja presion
CLASE_03 = keys[2]   # Inyectores sucios o filtro de combustible obstruido
CLASE_04 = keys[3]   # Falla en sensor de oxigeno o mezcla rica
CLASE_05 = keys[4]   # Cuerpo de aceleracion o valvula IAC sucia
CLASE_06 = keys[5]   # Empaque de culata soplado o danado
CLASE_07 = keys[6]   # Falla en termostato o motoventilador de radiador
CLASE_08 = keys[7]   # Fuga en mangueras de refrigerante o radiador picado
CLASE_09 = keys[8]   # Consumo de aceite por desgaste de anillos o retenes
CLASE_10 = keys[9]   # Baja presion de aceite o bomba de aceite defectuosa
CLASE_11 = keys[10]  # Faja o cadena de distribucion destensada o con salto de punto
CLASE_12 = keys[11]  # Falla en sistema de sincronizacion variable de valvulas (VVT / VVT-i / Valvetronic)
CLASE_13 = keys[12]  # Falla de descarbonizacion e inyeccion directa GDI (acumulacion de carbon en valvulas)

MACRO_MOTOR = "MOTOR"
FUENTE = "SINTETICO_TEST_CIEGO"


def obtener_test10_parte1(offset: int = 1) -> List[Dict[str, str]]:
    casos = []
    idx = offset

    def agregar(clase, nivel, texto, lenguaje, condicion, sp, sn, dtc, req_p, es_c, c_cont, obs):
        nonlocal idx
        reg_id = f"TEST10-{idx:04d}"
        grp_id = f"G-TEST10-{idx:04d}"
        casos.append({
            "id": reg_id,
            "id_grupo": grp_id,
            "clase_objetivo": clase,
            "macro_sistema": MACRO_MOTOR,
            "nivel_informacion": nivel,
            "texto_usuario": texto,
            "tipo_lenguaje": lenguaje,
            "condicion_operacion": condicion,
            "sintomas_presentes": sp,
            "sintomas_negados": sn,
            "dtc": dtc,
            "requiere_pregunta": req_p,
            "es_contrastivo": es_c,
            "clase_contrastiva": c_cont,
            "fuente": FUENTE,
            "observaciones": obs
        })
        idx += 1

    # --- CLASE 01: Bujías / Bobinas (misfire) ---
    agregar(CLASE_01, "L1", "El motor tironea bastante feo cuando quiero pasar a otro carro.", "COTIDIANO", "ACELERACION_ADELANTAMIENTO", "tironeo_fuerte_al_acelerar", "NO_REPORTA", "", "SI", "NO", "", "L1 tironeo en aceleracion")
    agregar(CLASE_01, "L1", "tiembla mucho el carro cuando paro en la luz roja y parpadea la luz amarilla del motor", "WHATSAPP", "RALENTI_SEMAFORO", "temblor_ralenti, check_parpadea", "NO_REPORTA", "", "SI", "NO", "", "L1 temblor semaforo check parpadea")
    agregar(CLASE_01, "L2", "Motor de 4 cilindros vibra en subidas pronunciadas en 3ra marcha; al acelerar a fondo cabecea pero en bajada rueda suave sin jaloneos.", "TALLER", "CARGA_EN_PENDIENTE", "vibracion_bajo_carga, cabeceo_aceleracion_fondo", "falla_caja_cambios", "", "NO", "SI", keys[25], "L2 cabeceo en subida vs inyector")
    agregar(CLASE_01, "L2", "Al exigir potencia en carretera se siente corte de chispa en cilindro 2 con código P0302; bujía con electrodo quemado a 1.4 mm.", "TECNICO", "EXIGENCIA_CARRETERA", "corte_chispa_cilindro_2, bujia_abierta_1_4mm", "falla_presion_gasolina", "P0302", "NO", "SI", CLASE_02, "L2 corte chispa P0302 bujia abierta")
    agregar(CLASE_01, "L3", "Osciloscopio automotriz en primario de bobina individual (COP): cilindro 3 acusa tiempo de quemado de solo 0.65 ms con picos de tensión oscilantes de 420V; se descarta inyector con prueba de pulso de 2.8 ms normal y compresión en 175 psi.", "TECNICO", "DIAGNOSTICO_OSCILOSCOPIO_COP", "tiempo_quemado_corto_0_65ms, pico_420v_bobina_3", "falla_inyector, falla_compresion", "P0303", "NO", "SI", keys[24], "L3 oscilograma bobina COP cilindro 3 vs inyector")
    agregar(CLASE_01, "L3", "Registro de contadores de fallo en tiempo real: cilindro 4 registra 42 misfires por ciclo a 2200 RPM bajo carga dynamométrica; aislamiento de capuchón de silicona perforado con fuga de alta tensión hacia culata; compresión pareja de 180 psi en los 4 cilindros.", "TECNICO", "PRUEBA_BANCO_DINAMOMETRICO", "misfires_cilindro_4_contador, capuchon_aislamiento_perforado", "falla_baja_compresion", "P0304", "NO", "SI", keys[25], "L3 contador misfires cilindro 4 capuchon perforado")

    # --- CLASE 02: Bomba de gasolina ---
