    agregar(CLASE_02, "L1", "se apago andando despues de un bache y ya no se escucha el zumbidito del tanque al poner contacto", "WHATSAPP", "APAGADO_EN_MARCHA", "apaga_en_marcha, sin_zumbido_tanque", "NO_REPORTA", "", "SI", "NO", "", "L1 sin zumbido tanque tras bache")
    agregar(CLASE_02, "L2", "Vehículo pierde fuerza gradualmente tras 20 minutos de marcha hasta detenerse; al enfriarse 1 hora vuelve a encender; presión en riel cae de 45 a 15 psi con temperatura.", "TALLER", "POST_CALENTAMIENTO", "perdida_gradual_fuerza, presion_cae_15psi_en_caliente", "falla_bobina_ignicion", "", "NO", "SI", CLASE_01, "L2 presion cae a 15 psi en caliente vs bobina")
