    agregar(CLASE_03, "L3", "Diagnóstico de caída de presión en línea de combustible: manómetro diferencial antes y después del filtro de combustible acusa delta de 1.4 bar a 2500 RPM (filtro colmatado por sedimento ferroso); bomba de tanque genera 4.2 bar antes del filtro; chispa y bobinas con oscilograma impecable.", "TECNICO", "PRESION_DIFERENCIAL_FILTRO", "delta_filtro_1_4bar_colmatado, bomba_4_2bar_ok", "falla_chispa_bobinas", "", "NO", "SI", CLASE_02, "L3 delta filtro 1.4 bar bomba 4.2 bar ok")

    # --- CLASE 04: Sensor de oxígeno / mezcla rica ---
    agregar(CLASE_04, "L1", "El tubo de escape bota un olor fuertísimo como a nafta cruda y gasta el doble.", "COTIDIANO", "MARCHA_URBANA", "olor_combustible_crudo_escape, consumo_excesivo", "NO_REPORTA", "", "SI", "NO", "", "L1 olor nafta escape consumo alto")
