    agregar(CLASE_04, "L2", "Humo negro por el escape en aceleradas bruscas; bujías con hollín seco aterciopelado; sensor de oxígeno banco 1 sensor 1 no oscila y queda clavado en 0.92V.", "TALLER", "INSPECCION_ESCANER", "humo_negro_aceleracion, o2_clavado_0_92v", "falla_empaque_culata", "P0172", "NO", "SI", CLASE_06, "L2 humo negro O2 clavado 0.92V P0172")
