    agregar(CLASE_04, "L3", "Verificación con osciloscopio automotriz en sensor de oxígeno circonio de 4 cables: tiempo de conmutación rico-a-pobre es de 980 ms (tolerancia máxima OEM 300 ms, sensor contaminado por silicio y envejecido); resistencia del calefactor interno mide 14 Ohmios conforme a 20°C.", "TECNICO", "OSCILOSCOPIO_SONDA_LAMBDA", "conmutacion_lenta_980ms_vs_300ms, calefactor_14_ohmios_ok", "falla_calefactor_o2", "", "NO", "SI", CLASE_03, "L3 conmutacion lenta 980ms sensor agotado")

